import{_ as r,a0 as s,w as p,s as u,ao as a,I as n,x as i,a1 as l,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"CI/CD 中的自動化測試的概要知識 | LCTT x X-CMD","titleTemplate":false,"description":"CI/CD 中的自動化測試的概要知識 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CI/CD 中的自動化測試的概要知識 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CI/CD 中的自動化測試的概要知識 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200709 What you need to know about automation testing in CI-CD","title":"CI/CD 中的自動化測試的概要知識","tag":"202007","desc":""},"relativePath":"202007/20200709 What you need to know about automation testing in CI-CD.md","filePath":"[post].md"}'),d={name:"202007/20200709 What you need to know about automation testing in CI-CD.md"};function C(m,t,g,f,T,b){const o=s("Link");return p(),u("div",null,[t[22]||(t[22]=a('<h1 id="ci-cd-中的自動化測試的概要知識" tabindex="-1">CI/CD 中的自動化測試的概要知識 <a class="header-anchor" href="#ci-cd-中的自動化測試的概要知識" aria-label="Permalink to “CI/CD 中的自動化測試的概要知識”">​</a></h1><blockquote><p>持續集成和持續交付是由測試驅動的。以下是如何做到的。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/27/210026blobu65f77accbob.jpg" alt=""></p><blockquote><p>“如果一切似乎都在控制之中，那只是你走的不夠快而已。” —Mario Andretti</p></blockquote><p>測試自動化是指在軟件開發過程中儘可能早、儘可能快地持續關注檢測缺陷、錯誤和 bug。這是通過使用那些追求質量為最高價值的工具完成的，它們旨在<em>確保</em>質量，而不僅僅是追求質量。</p><p>持續集成/持續交付（CI/CD）解決方案（也稱為 DevOps 管道）最引人注目的功能之一是可以更頻繁地進行測試，而又不會給開發人員或操作人員增加更多的手動工作。讓我們談談為什麼這很重要。</p><h3 id="為什麼要在-ci-cd-中實現自動化測試" tabindex="-1">為什麼要在 CI/CD 中實現自動化測試？ <a class="header-anchor" href="#為什麼要在-ci-cd-中實現自動化測試" aria-label="Permalink to “為什麼要在 CI/CD 中實現自動化測試？”">​</a></h3>',7)),n("p",null,[t[1]||(t[1]=i("敏捷團隊要更快的迭代，以更高的速度交付軟件和客户滿意度，而這些壓力可能會危及質量。全球競爭製造了對缺陷的",-1)),t[2]||(t[2]=n("em",null,"低容忍度",-1)),t[3]||(t[3]=i("，同時也增加了敏捷團隊的壓力，要求軟件交付的",-1)),t[4]||(t[4]=n("em",null,"迭代更快",-1)),t[5]||(t[5]=i("。減輕這種壓力的行業解決方案是什麼？是 ",-1)),l(o,{href:"https://opensource.com/resources/devops"},{default:e(()=>[...t[0]||(t[0]=[i("DevOps",-1)])]),_:1}),t[6]||(t[6]=i("。",-1))]),t[23]||(t[23]=a('<p>DevOps 是一個大概念，有很多定義，但是對 DevOps 成功至關重要的一項技術是 CI/CD。通過軟件開發流程設計一個連續的改進循環，可以為測試帶來新的機會。</p><h3 id="這對測試人員意味着什麼" tabindex="-1">這對測試人員意味着什麼？ <a class="header-anchor" href="#這對測試人員意味着什麼" aria-label="Permalink to “這對測試人員意味着什麼？”">​</a></h3><p>對於測試人員，這通常意味着他們必須：</p><ul><li>更早且更頻繁地進行測試（使用自動化）</li><li>持續測試“真實世界”的工作流（自動和手動）</li></ul><p>更具體地説，任何形式的測試，無論是由編寫代碼的開發人員運行還是由質量保證工程師團隊設計，其作用都是利用 CI/CD 基礎架構在快速推進的同時提高質量。</p><h3 id="測試人員還需要做什麼" tabindex="-1">測試人員還需要做什麼？ <a class="header-anchor" href="#測試人員還需要做什麼" aria-label="Permalink to “測試人員還需要做什麼？”">​</a></h3><p>具體點説，測試人員負責：</p><ul><li>測試新的和現有的軟件應用</li><li>根據系統要求評估軟件來驗證和確認功能</li><li>利用自動化測試工具來開發和維護可重複使用的自動化測試</li><li>與 scrum 團隊的所有成員合作，瞭解正在開發的功能以及實施的技術設計，以設計和開發準確、高質量的自動化測試</li><li>分析記錄在案的用户需求，並針對中等到高度複雜的軟件或 IT 系統制定或協助設計測試計劃</li><li>開發自動化測試，並與功能團隊一起審查和評估測試方案</li><li>與技術團隊合作，確定在開發環境中自動化測試的正確方法</li><li>與團隊合作，通過自動化測試來了解和解決軟件問題，並回應有關修改或增強的建議</li><li>參與需求梳理、估算和其他敏捷 scrum 儀式</li><li>協助制定標準和流程，以支持測試活動和材料（例如腳本、配置、程序、工具、計劃和結果）</li></ul><p>測試是一項艱鉅的工作，但這是有效構建軟件的重要組成部分。</p><h3 id="哪些持續測試很重要" tabindex="-1">哪些持續測試很重要？ <a class="header-anchor" href="#哪些持續測試很重要" aria-label="Permalink to “哪些持續測試很重要？”">​</a></h3><p>你可以使用多種測試。不同的類型並不是學科之間的牢固界限。相反，它們是表示如何測試的不同方式。比較測試類型不太重要，更重要的是對每一種測試類型都要有覆蓋率。</p><ul><li><strong>功能測試：</strong> 確保軟件具有其要求的功能</li><li><strong>單元測試：</strong> 獨立測試軟件的較小單元/組件以檢查其功能</li><li><strong>負載測試：</strong> 測試軟件在重負載或使用期間的性能</li><li><strong>壓力測試：</strong> 確定軟件承受壓力（最大負載）時的斷點</li><li><strong>集成測試：</strong> 測試組合或集成的一組組件的輸出</li><li><strong>迴歸測試：</strong> 當修改任意組件（無論多麼小），測試整個應用的功能</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>任何包含持續測試的軟件開發過程都將朝着建立關鍵反饋環路的方向發展，以實現快速和構建有效的軟件。最重要的是，該實踐將質量內置到 CI/CD 管道中，並意味着瞭解在軟件開發生命週期中提高速度同時減少風險和浪費之間的聯繫。</p><hr>',15)),n("p",null,[t[8]||(t[8]=i("via: ",-1)),l(o,{href:"https://opensource.com/article/20/7/automation-testing-cicd"},{default:e(()=>[...t[7]||(t[7]=[i("https://opensource.com/article/20/7/automation-testing-cicd",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=i("作者：",-1)),l(o,{href:"https://opensource.com/users/heronthecli"},{default:e(()=>[...t[9]||(t[9]=[i("Taz Brown",-1)])]),_:1}),t[14]||(t[14]=i(" 選題：",-1)),l(o,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[10]||(t[10]=[i("lujun9972",-1)])]),_:1}),t[15]||(t[15]=i(" 譯者：",-1)),l(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[11]||(t[11]=[i("geekpi",-1)])]),_:1}),t[16]||(t[16]=i(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[12]||(t[12]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=i("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[17]||(t[17]=[i("LCTT",-1)])]),_:1}),t[20]||(t[20]=i(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:e(()=>[...t[18]||(t[18]=[i("Linux中國",-1)])]),_:1}),t[21]||(t[21]=i(" 榮譽推出",-1))])])}const x=r(d,[["render",C]]);export{k as __pageData,x as default};
